NPWSX027.ol:
###################################################################################################
#
# Characterize double EDAC errors in the PCDU A EEPROM memory for Reconfiguration Table 3
#
#  Description: The PCDU raises the REC1 EDAC double error flag whenever it passes through 
#               uninitialised memory as per SOL.CRS.UM.00020, section 6.3.5
#
#               If non-initialized memory areas are read using SA28T, EDAC flags will indicate 
#               simple or double error. This is because EDAC information has not been stored in 
#               memory.
#
#               This synthetic also checks the checked address against the defined ranges and
#               sets accordingly the result value so that only in meaningful cases an alarm is
#               raised.
#
#               The defined memory ranges are as follows
#                  Reconfiguration Table #1: 0x4000 to 0x4100 (16384 to 16640) 
#                  Reconfiguration Table #2: 0x4100 to 0x4200 (16640 to 16896) 
#                  Reconfiguration Table #3: 0x4200 to 0x4300 (16896 to 17152) 
#                  Reconfiguration Table #4: 0x4300 to 0x4400 (17152 to 17408) 
#                                Empty Area: 0x4400 to 0x8000 (17408 to 32768) 
#
#  Return values: The following values are returned
#                    If NPWD0799 == OK then 0 is returned
#                    If NPWD0799 == NOK and NPWD6502 in the Reconfiguration Table #3 range then 1 is returned
#                    If NPWD0799 == NOK and NPWD6502 in any other range then 0 is returned
#                               
###################################################################################################


# Define the memory ranges
VAR_REC_1_START := 16384;
VAR_REC_1_END := 16640;
VAR_REC_2_START := 16640;
VAR_REC_2_END := 16896;
VAR_REC_3_START := 16896;
VAR_REC_3_END := 17152;
VAR_REC_4_START := 17152;
VAR_REC_4_END := 17408;
VAR_EMPTY_START := 17408;
VAR_EMPTY_END := 32768;


# Double EDAC error detected in EEPROM Reconfiguration Table 3
if (NPWD0799.eng == "NOK") then

  # Check if the error address is in the Reconfiguration Table 1 range
  if ((NPWD6502.raw >= VAR_REC_1_START) land (NPWD6502.raw < VAR_REC_1_END)) then
	 # Return the OK code as this is not the reconfiguration table corresponding to the parameter
     return(0);
  endif;

  # Check if the error address is in the Reconfiguration Table 2 range
  if ((NPWD6502.raw >= VAR_REC_2_START) land (NPWD6502.raw < VAR_REC_2_END)) then
     # Return the OK code as this is not the reconfiguration table corresponding to the parameter
     return(0);
  endif;

  # Check if the error address is in the Reconfiguration Table 3 range
  if ((NPWD6502.raw >= VAR_REC_3_START) land (NPWD6502.raw < VAR_REC_3_END)) then
     # Return the NOK code for the reconfiguration table #3
     return(1);
  endif;

  # Check if the error address is in the Reconfiguration Table 4 range
  if ((NPWD6502.raw >= VAR_REC_4_START) land (NPWD6502.raw < VAR_REC_4_END)) then
     # Return the OK code as this is not the reconfiguration table corresponding to the parameter
     return(0);
  endif;

else
     # No error detected
     return(0);
endif;

NPWSX052.ol:
# The following synthetic makes an assessment on the current configuration of the METIS decontamination heaters.
#
# The nominal Relaybox LCL configuration is for both of them to be ON.
#
# Only one of the two METIS decontamination heaters should be switched on at any time.
#
# The synthetic will return an integer status based on the discovered configuration. Note that this is used as an applicability value
# for the OOL sets on the temperatures of the respective thermal lines.
#
#  0 : NOMINAL OFF    ==> Both LCLs On or Off, Both Heaters OFF
#  1 : NOMINAL  ON    ==> Both LCLs On, Only one Heater On
#  2 : INCORRECT CONF ==> ((One LCL on, one LCL off) AND (All HTR configurations)) OR ((All LCL configurations) AND (Both HTRs on))
#
#

# Define return values
VAR_NOMINAL_OFF := 0;
VAR_NOMINAL_ON := 1;
VAR_INCORRECT_CONF := 2;

# Get TTR CPDU SCV status
VAR_TTR_CPDU_A_STATUS := NCSG0740.eng;
VAR_TTR_CPDU_B_STATUS := NCSG0750.eng;

# Get PCDU SCV status
VAR_PCDU_A_STATUS := NCSG0PC0.eng;
VAR_PCDU_B_STATUS := NCSG0PD0.eng;

# If PCDU-A is active
if (VAR_PCDU_A_STATUS ==  "ON_ON_ON") then
	# Get Relaybox LCLs statuses from PCDU-A
	VAR_DEC_LCL_1_ST := NPWD0050.eng;
	VAR_DEC_LCL_2_ST := NPWD0010.eng;
else
	# Get Relaybox LCLs statuses from PCDU-B
	VAR_DEC_LCL_1_ST := NPWT0050.eng;
	VAR_DEC_LCL_2_ST := NPWT0010.eng;
endif;

# If TTR CPDU A is ON
if (VAR_TTR_CPDU_A_STATUS ==  "ON_ON_ON") then
	# Get METIS Nominal and Redundant heater statuses from TTR CPDU-A
	VAR_METIS_HTR_A := NCD2Z00S.eng;
	VAR_METIS_HTR_B := NCD2Z017.eng;
else
	# Get METIS Nominal and Redundant heater statuses from TTR CPDU-B
	VAR_METIS_HTR_A := NCD2Z02S.eng;
	VAR_METIS_HTR_B := NCD2Z037.eng;
endif;

#
# Check status of LCLs
#
if ((VAR_DEC_LCL_1_ST == "ON") land (VAR_DEC_LCL_2_ST == "ON")) then
        #
        # Both Relaybox LCLs are ON
        #
        # Check status of METIS Prime and Redundant heaters
        #
        if ((VAR_METIS_HTR_A == "On") land (VAR_METIS_HTR_B == "On")) then
                # Both heaters are ON ==> INCORRECT CONF 
                return(VAR_INCORRECT_CONF);
        endif;

        if ((VAR_METIS_HTR_A == "Off") land (VAR_METIS_HTR_B == "Off")) then
                # Both heaters are OFF ==> NOMINAL OFF 
                return(VAR_NOMINAL_OFF);
        endif;

        # One heater is ON and the other OFF ==> NOMINAL ON
        return(VAR_NOMINAL_ON);

endif;

if ((VAR_DEC_LCL_1_ST == "OFF") land (VAR_DEC_LCL_2_ST == "OFF")) then
        #
        # Both Relaybox LCLs are OFF
        #
        # Check status of METIS Prime and Redundant heaters
        #
        if ((VAR_METIS_HTR_A == "Off") land (VAR_METIS_HTR_B == "Off")) then
	        # Both heaters are OFF ==> NOMINAL OFF configuration
                return(VAR_NOMINAL_OFF);
        endif;

        # At least on heater is ON ==> INCORRECT CONF
        return(VAR_INCORRECT_CONF);
endif;

#
# One Relaybox LCL is ON and the other is OFF ==> INCORRECT CONF
#
return(VAR_INCORRECT_CONF);

